-- 커뮤니티 탭의 배너. 관리 API 없이 운영자가 로컬 관리 페이지(admin-local)나 SQL로 직접 넣고 고친다.
-- 관리 페이지가 SQL로 바로 넣으므로 생성·수정 시각에 기본값을 둔다.
-- 노출 시각은 시작을 포함하고 만료를 제외한다. 비어 있으면 해당 시작·종료 제한이 없다.
CREATE TABLE "banners" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "type" VARCHAR(20) NOT NULL,
    "brand_name" VARCHAR(50) NOT NULL,
    "brand_category" VARCHAR(30),
    "title" VARCHAR(100) NOT NULL,
    "image_url" VARCHAR(512) NOT NULL,
    "link_url" VARCHAR(1024) NOT NULL,
    "link_label" VARCHAR(30),
    "brand_description" VARCHAR(500),
    "benefit_description" VARCHAR(100),
    "usage_location" VARCHAR(100),
    "promotion_code" VARCHAR(50),
    "starts_at" TIMESTAMP WITH TIME ZONE,
    "expires_at" TIMESTAMP WITH TIME ZONE,
    "sort_order" INTEGER NOT NULL DEFAULT 0,
    "active" BOOLEAN NOT NULL DEFAULT TRUE,
    "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "chk_banners_type" CHECK ("type" IN ('BENEFIT', 'INTRODUCTION')),
    CONSTRAINT "chk_banners_benefit_fields" CHECK (
        "type" <> 'BENEFIT'
        OR ("benefit_description" IS NOT NULL AND "usage_location" IS NOT NULL
            AND "starts_at" IS NOT NULL AND "expires_at" IS NOT NULL)
    ),
    CONSTRAINT "chk_banners_introduction_fields" CHECK (
        "type" <> 'INTRODUCTION' OR ("brand_description" IS NOT NULL AND "link_label" IS NOT NULL)
    ),
    CONSTRAINT "chk_banners_period" CHECK ("starts_at" IS NULL OR "expires_at" IS NULL OR "starts_at" < "expires_at")
);

CREATE INDEX "idx_banners_active_sort" ON "banners" ("active", "sort_order");

COMMENT ON COLUMN banners.brand_category IS '업종';
